create table if not exists public.messages (id uuid primary key default gen_random_uuid(), connection_id uuid not null references public.connections(id) on delete cascade, sender_id uuid not null references public.profiles(id) on delete cascade, recipient_id uuid not null references public.profiles(id) on delete cascade, content text not null check(length(trim(content)) between 1 and 4000), is_read boolean not null default false, created_at timestamptz not null default now());
alter table public.messages add column if not exists connection_id uuid; alter table public.messages add column if not exists sender_id uuid; alter table public.messages add column if not exists recipient_id uuid; alter table public.messages add column if not exists content text; alter table public.messages add column if not exists is_read boolean not null default false; alter table public.messages add column if not exists created_at timestamptz default now();
